package storage

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
)

// LabelEvent records the human judgment for an event. Relabeling replaces the
// prior judgment so the export always contains one current answer per event.
func (d *DB) LabelEvent(eventID, category string, requiresAction bool, expectedOutcome string) (*EventLabel, error) {
	category = strings.TrimSpace(category)
	if category == "" {
		return nil, fmt.Errorf("category is required")
	}
	if expectedOutcome != "ignore" && expectedOutcome != "notify" {
		return nil, fmt.Errorf("expected outcome must be ignore or notify")
	}
	var exists int
	if err := d.QueryRow(`SELECT 1 FROM events WHERE id = ?`, eventID).Scan(&exists); err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("event %s not found", eventID)
		}
		return nil, fmt.Errorf("find event %s: %w", eventID, err)
	}

	label := &EventLabel{
		EventID:         eventID,
		Category:        category,
		RequiresAction:  requiresAction,
		ExpectedOutcome: expectedOutcome,
		LabeledAt:       time.Now().UTC(),
	}
	_, err := d.Exec(`INSERT INTO event_labels (event_id, category, requires_action, expected_outcome, labeled_at)
		VALUES (?, ?, ?, ?, ?)
		ON CONFLICT(event_id) DO UPDATE SET
			category = excluded.category,
			requires_action = excluded.requires_action,
			expected_outcome = excluded.expected_outcome,
			labeled_at = excluded.labeled_at`,
		label.EventID, label.Category, label.RequiresAction, label.ExpectedOutcome, label.LabeledAt.Format(time.RFC3339Nano))
	if err != nil {
		return nil, fmt.Errorf("label event %s: %w", eventID, err)
	}
	return label, nil
}

// ListEvents returns recent events with their latest decision, execution, and
// optional human label. It is the backing query for the local review queue.
func (d *DB) ListEvents(limit int, unlabeledOnly bool) ([]ReviewEvent, error) {
	if limit <= 0 {
		return nil, fmt.Errorf("limit must be positive")
	}
	where := ""
	if unlabeledOnly {
		where = "WHERE l.event_id IS NULL"
	}
	rows, err := d.Query(`
SELECT e.id, e.type, e.source, e.subject, e.event_time, e.data, e.metadata,
       d.id, d.interpreter, d.model, d.status, d.result, d.latency_ms, d.error,
       x.outcome,
       l.category, l.requires_action, l.expected_outcome, l.labeled_at
FROM events e
LEFT JOIN decisions d ON d.id = (
	SELECT id FROM decisions WHERE event_id = e.id ORDER BY created_at DESC LIMIT 1
)
LEFT JOIN executions x ON x.id = (
	SELECT id FROM executions WHERE event_id = e.id ORDER BY created_at DESC LIMIT 1
)
LEFT JOIN event_labels l ON l.event_id = e.id
`+where+`
ORDER BY e.ingest_time DESC
LIMIT ?`, limit)
	if err != nil {
		return nil, fmt.Errorf("list events: %w", err)
	}
	defer rows.Close()

	var events []ReviewEvent
	for rows.Next() {
		var (
			id, typ, source, subject, eventTime string
			dataJSON, metadataJSON              sql.NullString
			decisionID, interpreter, modelName  sql.NullString
			decisionStatus, resultJSON          sql.NullString
			latency                             sql.NullInt64
			decisionErr, outcome                sql.NullString
			category, expectedOutcome           sql.NullString
			requiresAction                      sql.NullInt64
			labeledAt                           sql.NullString
		)
		if err := rows.Scan(
			&id, &typ, &source, &subject, &eventTime, &dataJSON, &metadataJSON,
			&decisionID, &interpreter, &modelName, &decisionStatus, &resultJSON, &latency, &decisionErr,
			&outcome, &category, &requiresAction, &expectedOutcome, &labeledAt,
		); err != nil {
			return nil, fmt.Errorf("scan event: %w", err)
		}
		e, err := decodeStoredEvent(id, typ, source, subject, eventTime, dataJSON, metadataJSON)
		if err != nil {
			return nil, err
		}
		review := ReviewEvent{Event: e, Outcome: outcome.String}
		if decisionID.Valid {
			dec := &event.Decision{
				ID: decisionID.String, EventID: id, Interpreter: interpreter.String,
				Model: modelName.String, Status: decisionStatus.String,
				LatencyMs: latency.Int64, Error: decisionErr.String,
			}
			if resultJSON.Valid && resultJSON.String != "null" {
				if err := json.Unmarshal([]byte(resultJSON.String), &dec.Result); err != nil {
					return nil, fmt.Errorf("decode decision %s result: %w", dec.ID, err)
				}
			}
			review.Decision = dec
		}
		if category.Valid {
			at, err := time.Parse(time.RFC3339Nano, labeledAt.String)
			if err != nil {
				return nil, fmt.Errorf("decode label for event %s: %w", id, err)
			}
			review.Label = &EventLabel{
				EventID: id, Category: category.String, RequiresAction: requiresAction.Int64 != 0,
				ExpectedOutcome: expectedOutcome.String, LabeledAt: at,
			}
		}
		events = append(events, review)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list events: %w", err)
	}
	return events, nil
}

// LabeledEvents returns every labeled event in stable ingestion order for
// deterministic JSONL exports.
func (d *DB) LabeledEvents() ([]LabeledEvent, error) {
	rows, err := d.Query(`
SELECT e.id, e.type, e.source, e.subject, e.event_time, e.data, e.metadata,
       l.category, l.requires_action, l.expected_outcome, l.labeled_at
FROM event_labels l
JOIN events e ON e.id = l.event_id
ORDER BY e.ingest_time, e.id`)
	if err != nil {
		return nil, fmt.Errorf("list labeled events: %w", err)
	}
	defer rows.Close()

	var events []LabeledEvent
	for rows.Next() {
		var (
			id, typ, source, subject, eventTime string
			dataJSON, metadataJSON              sql.NullString
			category, expectedOutcome           string
			requiresAction                      bool
			labeledAt                           string
		)
		if err := rows.Scan(&id, &typ, &source, &subject, &eventTime, &dataJSON, &metadataJSON,
			&category, &requiresAction, &expectedOutcome, &labeledAt); err != nil {
			return nil, fmt.Errorf("scan labeled event: %w", err)
		}
		e, err := decodeStoredEvent(id, typ, source, subject, eventTime, dataJSON, metadataJSON)
		if err != nil {
			return nil, err
		}
		at, err := time.Parse(time.RFC3339Nano, labeledAt)
		if err != nil {
			return nil, fmt.Errorf("decode label for event %s: %w", id, err)
		}
		events = append(events, LabeledEvent{Event: e, Label: EventLabel{
			EventID: id, Category: category, RequiresAction: requiresAction,
			ExpectedOutcome: expectedOutcome, LabeledAt: at,
		}})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list labeled events: %w", err)
	}
	return events, nil
}

func decodeStoredEvent(id, typ, source, subject, eventTime string, dataJSON, metadataJSON sql.NullString) (event.Event, error) {
	at, err := time.Parse(time.RFC3339Nano, eventTime)
	if err != nil {
		return event.Event{}, fmt.Errorf("decode event %s time: %w", id, err)
	}
	e := event.Event{ID: id, Type: typ, Source: source, Subject: subject, Timestamp: at}
	if dataJSON.Valid && dataJSON.String != "null" {
		if err := json.Unmarshal([]byte(dataJSON.String), &e.Data); err != nil {
			return event.Event{}, fmt.Errorf("decode event %s data: %w", id, err)
		}
	}
	if metadataJSON.Valid && metadataJSON.String != "null" {
		if err := json.Unmarshal([]byte(metadataJSON.String), &e.Metadata); err != nil {
			return event.Event{}, fmt.Errorf("decode event %s metadata: %w", id, err)
		}
	}
	return e, nil
}

// Trace persistence and the single-event inspection query. The trace is
// written once, after the pipeline has finished with an event: the steps
// describe work that already happened, so there is nothing to gain from
// writing them incrementally and something to lose — a second write per
// stage on the synchronous ingest path.
package storage

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
)

// InsertTrace persists an event's pipeline trace in one transaction, so an
// inspected trace is either the whole story or absent — a half-written
// trace would read as "the runtime stopped at policy" and be a lie.
//
// Steps are stored with their arrival order (seq) and read back by it
// rather than by timestamp: steps within one event can share a clock tick,
// and the sequence is what actually happened.
func (d *DB) InsertTrace(eventID string, steps []event.TraceStep) error {
	if len(steps) == 0 {
		return nil
	}
	tx, err := d.Begin()
	if err != nil {
		return fmt.Errorf("insert trace %s: %w", eventID, err)
	}
	defer tx.Rollback() // no-op once committed; covers every error return below

	stmt, err := tx.Prepare(`INSERT INTO event_traces (event_id, seq, at, stage, msg) VALUES (?, ?, ?, ?, ?)`)
	if err != nil {
		return fmt.Errorf("insert trace %s: %w", eventID, err)
	}
	defer stmt.Close()
	for i, s := range steps {
		if _, err := stmt.Exec(eventID, i, s.At.UTC().Format(time.RFC3339Nano), s.Stage, s.Msg); err != nil {
			return fmt.Errorf("insert trace %s step %d: %w", eventID, i, err)
		}
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("insert trace %s: %w", eventID, err)
	}
	return nil
}

// EventTrace returns one event's trace in pipeline order.
func (d *DB) EventTrace(eventID string) ([]event.TraceStep, error) {
	rows, err := d.Query(`SELECT at, stage, msg FROM event_traces WHERE event_id = ? ORDER BY seq`, eventID)
	if err != nil {
		return nil, fmt.Errorf("read trace %s: %w", eventID, err)
	}
	defer rows.Close()

	var steps []event.TraceStep
	for rows.Next() {
		var at, stage, msg string
		if err := rows.Scan(&at, &stage, &msg); err != nil {
			return nil, fmt.Errorf("scan trace %s: %w", eventID, err)
		}
		ts, err := time.Parse(time.RFC3339Nano, at)
		if err != nil {
			return nil, fmt.Errorf("decode trace %s step time: %w", eventID, err)
		}
		steps = append(steps, event.TraceStep{At: ts, Stage: stage, Msg: msg})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read trace %s: %w", eventID, err)
	}
	return steps, nil
}

// Inspect assembles everything stored about one event. It reads across four
// tables without a transaction: the pipeline is finished with an event by
// the time anyone inspects it, so there is no writer to race with, and a
// read transaction on the single shared connection would block ingest for
// no benefit.
func (d *DB) Inspect(eventID string) (*Inspection, error) {
	var (
		id, typ, source, subject, eventTime string
		dataJSON, metadataJSON              sql.NullString
	)
	err := d.QueryRow(`SELECT id, type, source, subject, event_time, data, metadata FROM events WHERE id = ?`, eventID).
		Scan(&id, &typ, &source, &subject, &eventTime, &dataJSON, &metadataJSON)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("event %s not found", eventID)
	}
	if err != nil {
		return nil, fmt.Errorf("read event %s: %w", eventID, err)
	}
	e, err := decodeStoredEvent(id, typ, source, subject, eventTime, dataJSON, metadataJSON)
	if err != nil {
		return nil, err
	}
	ins := &Inspection{Event: e}

	if ins.Decisions, err = d.eventDecisions(eventID); err != nil {
		return nil, err
	}
	if ins.Executions, err = d.eventExecutions(eventID); err != nil {
		return nil, err
	}
	if ins.Trace, err = d.EventTrace(eventID); err != nil {
		return nil, err
	}
	if ins.Label, err = d.eventLabel(eventID); err != nil {
		return nil, err
	}
	return ins, nil
}

func (d *DB) eventDecisions(eventID string) ([]event.Decision, error) {
	rows, err := d.Query(`SELECT id, interpreter, model, status, result, latency_ms, error
		FROM decisions WHERE event_id = ? ORDER BY created_at, id`, eventID)
	if err != nil {
		return nil, fmt.Errorf("read decisions for %s: %w", eventID, err)
	}
	defer rows.Close()

	var out []event.Decision
	for rows.Next() {
		dec := event.Decision{EventID: eventID}
		var resultJSON, decErr sql.NullString
		if err := rows.Scan(&dec.ID, &dec.Interpreter, &dec.Model, &dec.Status, &resultJSON, &dec.LatencyMs, &decErr); err != nil {
			return nil, fmt.Errorf("scan decision for %s: %w", eventID, err)
		}
		dec.Error = decErr.String
		if resultJSON.Valid && resultJSON.String != "null" {
			if err := json.Unmarshal([]byte(resultJSON.String), &dec.Result); err != nil {
				return nil, fmt.Errorf("decode decision %s result: %w", dec.ID, err)
			}
		}
		out = append(out, dec)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read decisions for %s: %w", eventID, err)
	}
	return out, nil
}

func (d *DB) eventExecutions(eventID string) ([]Execution, error) {
	rows, err := d.Query(`SELECT id, decision_id, outcome, adapter, status, error, created_at
		FROM executions WHERE event_id = ? ORDER BY created_at, id`, eventID)
	if err != nil {
		return nil, fmt.Errorf("read executions for %s: %w", eventID, err)
	}
	defer rows.Close()

	var out []Execution
	for rows.Next() {
		x := Execution{EventID: eventID}
		var decisionID, adapter, execErr sql.NullString
		var createdAt string
		if err := rows.Scan(&x.ID, &decisionID, &x.Outcome, &adapter, &x.Status, &execErr, &createdAt); err != nil {
			return nil, fmt.Errorf("scan execution for %s: %w", eventID, err)
		}
		x.DecisionID, x.Adapter, x.Error = decisionID.String, adapter.String, execErr.String
		at, err := time.Parse(time.RFC3339Nano, createdAt)
		if err != nil {
			return nil, fmt.Errorf("decode execution %s time: %w", x.ID, err)
		}
		x.CreatedAt = at
		out = append(out, x)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read executions for %s: %w", eventID, err)
	}
	return out, nil
}

func (d *DB) eventLabel(eventID string) (*EventLabel, error) {
	var (
		category, expectedOutcome, labeledAt string
		requiresAction                       bool
	)
	err := d.QueryRow(`SELECT category, requires_action, expected_outcome, labeled_at
		FROM event_labels WHERE event_id = ?`, eventID).
		Scan(&category, &requiresAction, &expectedOutcome, &labeledAt)
	if err == sql.ErrNoRows {
		return nil, nil // unlabeled is the common case, not an error
	}
	if err != nil {
		return nil, fmt.Errorf("read label for %s: %w", eventID, err)
	}
	at, err := time.Parse(time.RFC3339Nano, labeledAt)
	if err != nil {
		return nil, fmt.Errorf("decode label for event %s: %w", eventID, err)
	}
	return &EventLabel{
		EventID: eventID, Category: category, RequiresAction: requiresAction,
		ExpectedOutcome: expectedOutcome, LabeledAt: at,
	}, nil
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"strconv"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/storage"
)

func events(args []string) error {
	fs := flag.NewFlagSet("mrmr events", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	unlabeled := fs.Bool("unlabeled", false, "show only events without a human label")
	limit := fs.Int("limit", 20, "maximum events to show")
	if err := fs.Parse(args); err != nil {
		return err
	}
	if *limit < 1 || *limit > 1000 {
		return fmt.Errorf("events limit must be between 1 and 1000")
	}

	_, db, err := openConfigDB(*configPath)
	if err != nil {
		return err
	}
	defer db.Close()
	rows, err := db.ListEvents(*limit, *unlabeled)
	if err != nil {
		return err
	}
	enc := json.NewEncoder(os.Stdout)
	for _, row := range rows {
		if err := enc.Encode(row); err != nil {
			return fmt.Errorf("write events: %w", err)
		}
	}
	return nil
}

func label(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: mrmr label EVENT_ID -category CATEGORY -requires-action=true|false -outcome ignore|notify")
	}
	eventID := args[0]
	fs := flag.NewFlagSet("mrmr label", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	category := fs.String("category", "", "expected category")
	requiresActionText := fs.String("requires-action", "", "whether action is required: true or false")
	outcome := fs.String("outcome", "", "expected outcome: ignore or notify")
	if err := fs.Parse(args[1:]); err != nil {
		return err
	}
	if *category == "" || *requiresActionText == "" || *outcome == "" {
		return fmt.Errorf("category, requires-action, and outcome are required")
	}
	requiresAction, err := strconv.ParseBool(*requiresActionText)
	if err != nil {
		return fmt.Errorf("requires-action must be true or false")
	}

	cfg, db, err := openConfigDB(*configPath)
	if err != nil {
		return err
	}
	defer db.Close()
	if err := validateLabelCategory(cfg, *category); err != nil {
		return err
	}
	stored, err := db.LabelEvent(eventID, *category, requiresAction, *outcome)
	if err != nil {
		return err
	}
	return json.NewEncoder(os.Stdout).Encode(stored)
}

func dataset(args []string) error {
	if len(args) == 0 || args[0] != "export" {
		return fmt.Errorf("usage: mrmr dataset export [-config mrmr.yaml] [-output path|-]")
	}
	fs := flag.NewFlagSet("mrmr dataset export", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	output := fs.String("output", "-", "output JSONL path, or - for stdout")
	if err := fs.Parse(args[1:]); err != nil {
		return err
	}

	_, db, err := openConfigDB(*configPath)
	if err != nil {
		return err
	}
	defer db.Close()
	rows, err := db.LabeledEvents()
	if err != nil {
		return err
	}

	var out io.Writer = os.Stdout
	var file *os.File
	if *output != "-" {
		file, err = os.OpenFile(*output, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
		if err != nil {
			return fmt.Errorf("create dataset %s: %w", *output, err)
		}
		defer file.Close()
		out = file
	}
	if err := writeDataset(out, rows); err != nil {
		return err
	}
	fmt.Fprintf(os.Stderr, "exported %d labeled events\n", len(rows))
	return nil
}

func openConfigDB(path string) (*config.Config, *storage.DB, error) {
	cfg, err := config.Load(path)
	if err != nil {
		return nil, nil, err
	}
	db, err := storage.Open(cfg.DB.Path)
	if err != nil {
		return nil, nil, err
	}
	return cfg, db, nil
}

func validateLabelCategory(cfg *config.Config, category string) error {
	field, ok := cfg.Interpret.Schema["category"]
	if !ok || field.Type != "string" {
		return fmt.Errorf("labeling requires string interpret.schema field %q", "category")
	}
	if len(field.Enum) == 0 {
		return nil
	}
	for _, allowed := range field.Enum {
		if fmt.Sprint(allowed) == category {
			return nil
		}
	}
	return fmt.Errorf("category %q is not allowed by interpret.schema", category)
}

func writeDataset(w io.Writer, rows []storage.LabeledEvent) error {
	enc := json.NewEncoder(w)
	for _, row := range rows {
		tc := evalCase{Name: row.Event.ID, Event: row.Event}
		tc.Expected.Category = row.Label.Category
		tc.Expected.RequiresAction = new(bool)
		*tc.Expected.RequiresAction = row.Label.RequiresAction
		tc.Expected.Outcome = row.Label.ExpectedOutcome
		if err := enc.Encode(tc); err != nil {
			return fmt.Errorf("write dataset: %w", err)
		}
	}
	return nil
}

