// Package event defines the records that flow through mrmr's pipeline: the
// Event (what happened, normalized), the Decision (what the model thought it
// meant), and the TraceStep (why the runtime did what it did). These types
// are intentionally boring and dependency-free — every stage of the runtime
// handles them, so any cleverness here would be paid for everywhere. data
// and metadata are opaque maps: the core makes no assumptions about what a
// source puts in them, because assuming is how source-specific logic leaks
// into the runtime.
package event

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"time"
)

// Event is the normalized record of something that happened. Sources are
// dumb by design: they detect and emit, they never interpret. The runtime
// stamps ID and Timestamp at ingestion — a source's clock is not trusted,
// though a source may carry its original time inside data or metadata if
// the event itself needs it.
type Event struct {
	ID        string         `json:"id"`
	Type      string         `json:"type"`
	Source    string         `json:"source"`
	Subject   string         `json:"subject,omitempty"`
	Timestamp time.Time      `json:"timestamp"` // event time, UTC
	Data      map[string]any `json:"data,omitempty"`
	Metadata  map[string]any `json:"metadata,omitempty"`
	// Depth is the causal hop count for events mrmr emitted itself
	// (emit-event actions, delegated-agent completions). Externally sourced
	// events are 0; each emit increments. The runtime forces ignore past its
	// max so a flow pair that emits into each other cannot recurse forever.
	Depth int `json:"depth,omitempty"`
}

// Decision is the validated result of interpreting an Event. Status is the
// axis the rest of the runtime cares about: "ok" decisions reach policy;
// "invalid" (schema failure after retry) and "errored" (endpoint failure)
// both route to ignore. Decisions persist even when they fail, because "the
// model was down at 3am" is a question worth answering from the audit trail.
type Decision struct {
	ID          string         `json:"id"`
	EventID     string         `json:"event_id"`
	Interpreter string         `json:"interpreter"` // model config name
	Model       string         `json:"model"`       // actual model id sent to endpoint
	Status      string         `json:"status"`
	Result      map[string]any `json:"result,omitempty"`
	LatencyMs   int64          `json:"latency_ms"`
	Error       string         `json:"error,omitempty"`
}

// TraceStep is one observable moment in an Event's journey through the
// pipeline: receive, persist, filter, interpret, policy, outcome. The trace
// is mrmr's answer to "why did this happen?" — it must be possible to
// explain any outcome by reading nothing but the trace, which is why the
// trace is durable rather than only returned to whoever posted the event.
//
// A step carries the validated Decision result when that is what the stage
// produced, but never a prompt and never a raw model response: those are
// opt-in debug capture, never normal audit data.
type TraceStep struct {
	At    time.Time `json:"at"`
	Stage string    `json:"stage"`
	Msg   string    `json:"msg,omitempty"`
}

// NewID returns a sortable unique id: prefix + hex(unix-millis + random).
// ponytail: hand-rolled instead of a ULID dep; swap if cross-system ordering matters.
func NewID(prefix string) string {
	var b [10]byte
	ms := time.Now().UnixMilli()
	for i := 0; i < 6; i++ {
		b[i] = byte(ms >> (8 * (5 - i)))
	}
	if _, err := rand.Read(b[6:]); err != nil {
		panic(fmt.Sprintf("new id: %v", err))
	}
	return prefix + hex.EncodeToString(b[:])
}

// Package filter applies deterministic checks to Events before any model
// call. It is the pipeline's cost gate (IMPLEMENTATION.md section 3):
// events that ordinary code can already exclude must not spend inference.
// Evaluation is pure: no I/O, no clock, no model. A filter can never
// fail in a way a model can, which is what makes the excluded path safe
// by construction.
//
// Two rules shape this package.
//
// Fail toward ignore. The filter is the only gate before policy, and
// policy is what authorizes outcomes. An event that cannot be resolved
// (missing field, malformed path, incomparable type) fails every
// comparison and is excluded, never passed by default. A malformed
// event that slips past the gate is one good model day from an outcome
// nobody authorized.
//
// Reasons are value-free. Failure reasons flow into the trace, the HTTP
// response, and stdout, and event payloads may be sensitive. A reason
// carries the rule index, field path, and operator only.
//
// This package does not reuse policy's comparisons on purpose. Filter
// ops are named (eq, neq) and compared by strict semantic type; policy
// conditions are operator-expression strings compared by fmt.Sprint.
// The gate is where a type-shifted value becomes a bypass, so it must
// not inherit the looser semantics. If a future third caller really
// shares one of these semantics, extract a neutral condition package
// then, not before.
package filter

import (
	"fmt"
	"math"
	"reflect"
	"strings"

	"github.com/heath0xff/mrmr/internal/event"
)

// Op is the comparison a Spec applies. v0.1 ships only the two
// comparisons the spec documents for filters: neq (excluding known
// senders such as bots) and eq, which is also the default when op is
// left empty. Numeric ordering lands when a real flow needs it; the
// Spec shape does not change.
type Op string

const (
	OpEq  Op = "eq"
	OpNeq Op = "neq"
)

// Spec is one filter line. All Specs in a List are ANDed, mirroring
// policy's condition semantics: alternatives are separate Specs, not OR.
type Spec struct {
	Field string `yaml:"field"`
	Op    Op     `yaml:"op"`
	Value any    `yaml:"value"`
}

// List is the ordered set of Specs. An empty list passes every event, so
// a config without a filter section behaves exactly as before.
type List []Spec

// fieldRoots are the only path roots a Spec may address. They are the
// Event's top-level fields, with data and metadata open to dot descent.
var fieldRoots = map[string]bool{
	"type":     true,
	"source":   true,
	"subject":  true,
	"data":     true,
	"metadata": true,
}

// normalizePath reduces a Spec's field to its canonical form and reports
// whether it addresses a value the runtime can compare. The spec
// documents both "data.author" (section 3) and "event.data.author" (the
// flow example); exactly one leading "event." is accepted, so both forms
// behave identically. Everything else is rejected at config time because
// a filter that can never match is a typo, not a choice: unknown roots,
// a bare data/metadata (a map can never compare), and sub-paths under
// scalar roots (a scalar can never have children).
func normalizePath(field string) (string, error) {
	if field == "" {
		return "", fmt.Errorf("field is required")
	}
	if strings.HasPrefix(field, "event.") {
		field = field[len("event."):]
	}
	parts := strings.Split(field, ".")
	for _, p := range parts {
		if p == "" {
			return "", fmt.Errorf("field %q: empty path segment", field)
		}
	}
	root := parts[0]
	if !fieldRoots[root] {
		return "", fmt.Errorf("field %q: unknown root %q (want type, source, subject, data, or metadata)", field, root)
	}
	switch root {
	case "type", "source", "subject":
		if len(parts) > 1 {
			return "", fmt.Errorf("field %q: %s has no sub-paths", field, root)
		}
	default:
		if len(parts) == 1 {
			return "", fmt.Errorf("field %q: %s requires a sub-path", field, root)
		}
	}
	return field, nil
}

// Validate reports whether the Spec can run correctly. Config calls it
// for every filter line, so a malformed filter refuses startup rather
// than mis-firing at request time.
func (s Spec) Validate() error {
	if _, err := normalizePath(s.Field); err != nil {
		return err
	}
	switch s.Op {
	case "", OpEq, OpNeq:
	default:
		return fmt.Errorf("op %q not supported (v0.1: eq, neq)", s.Op)
	}
	if s.Value == nil {
		return fmt.Errorf("field %q: value is required", s.Field)
	}
	if !valueOK(s.Value) {
		return fmt.Errorf("field %q: value must be a string, number, or boolean", s.Field)
	}
	return nil
}

// Evaluate reports whether e passes every Spec in order, and returns the
// first failure as a value-free reason (rule index, path, operator) for
// the trace. ok is true when the list is empty or every Spec passes.
func (l List) Evaluate(e event.Event) (bool, string) {
	for i, s := range l {
		path, err := normalizePath(s.Field)
		if err != nil {
			// Unreachable after config validation; fail closed anyway.
			// A Spec that cannot be parsed must exclude, not pass.
			return false, fmt.Sprintf("filter %d: malformed field", i+1)
		}
		got, present := resolve(e, path)
		if !present {
			// A missing field fails every operator, including neq: the
			// event cannot prove itself acceptable to the gate, and
			// exclusion is the only safe answer.
			return false, fmt.Sprintf("filter %d: field %s not present", i+1, path)
		}
		if !matches(s.Op, s.Value, got) {
			return false, fmt.Sprintf("filter %d: %s (%s) did not match", i+1, path, opName(s.Op))
		}
	}
	return true, ""
}

func opName(op Op) string {
	if op == "" {
		return string(OpEq)
	}
	return string(op)
}

// resolve walks a normalized dot path against the Event. Scalar roots
// resolve exactly; data and metadata descend into maps. Every miss
// (unknown key, a non-map mid-path, a map at the end, an empty scalar
// root) is "not present": resolution never guesses. Subject is
// optional, so an empty subject is not present. The same guard applies
// to type and source because Ingest can be called outside the HTTP
// handler, which is the only place that requires them non-empty.
func resolve(e event.Event, path string) (any, bool) {
	parts := strings.Split(path, ".")
	switch parts[0] {
	case "type":
		if e.Type != "" {
			return e.Type, true
		}
	case "source":
		if e.Source != "" {
			return e.Source, true
		}
	case "subject":
		if e.Subject != "" {
			return e.Subject, true
		}
	case "data":
		return walk(e.Data, parts[1:])
	case "metadata":
		return walk(e.Metadata, parts[1:])
	}
	return nil, false
}

// walk descends one level at a time. It is only called with a non-empty
// parts slice: normalizePath rejects a bare data/metadata root.
func walk(m map[string]any, parts []string) (any, bool) {
	cur, ok := m[parts[0]]
	if !ok {
		return nil, false
	}
	if len(parts) == 1 {
		return cur, true
	}
	next, ok := cur.(map[string]any)
	if !ok {
		return nil, false
	}
	return walk(next, parts[1:])
}

// kind is a value's semantic type. Anything that is not a number,
// string, or bool (nil, maps, slices) is opaque and comparable with
// nothing.
type kind int

const (
	kindNumber kind = iota
	kindString
	kindBool
	kindOpaque
)

func classify(v any) kind {
	switch v.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		return kindNumber
	case string:
		return kindString
	case bool:
		return kindBool
	}
	return kindOpaque
}

// toFloat normalizes a numeric value to float64, reporting whether the
// result is usable for a comparison. Non-finite inputs (NaN, Inf) are
// not comparable: NaN never equals itself, so an eq check can never
// match and a neq check would pass every value, malformed data
// included. They are reported incomparable instead of compared.
func toFloat(v any) (float64, bool) {
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return float64(rv.Int()), true
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return float64(rv.Uint()), true
	case reflect.Float32, reflect.Float64:
		f := rv.Float()
		return f, finite(f)
	}
	return 0, false // classify() guarantees a number here
}

// valueOK reports whether a Spec value can ever take part in a
// comparison. The comparator works on three semantic types: number,
// string, bool. Anything else (lists, maps, channels) can never
// match, and a filter line that can never match is a typo, not a
// choice: it must fail startup, not silently exclude every event at
// runtime. Numbers must be finite: NaN never equals itself, so it can
// never satisfy eq and would pass neq against every value; Inf is not
// a value a source will send. Both are unmatchable by construction.
func valueOK(v any) bool {
	switch n := v.(type) {
	case string, bool:
		return true
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return true
	case float32:
		return finite(float64(n))
	case float64:
		return finite(n)
	}
	return false
}

// finite reports whether a number can take part in a comparison.
// Shared by valueOK (config side) and toFloat (event side) so the
// non-finite rule has one definition.
func finite(f float64) bool {
	return !math.IsNaN(f) && !math.IsInf(f, 0)
}

// compare reports whether two values are equal, and whether they are
// comparable at all. Comparison is strict by semantic type on purpose,
// and intentionally stricter than policy.match's fmt.Sprint semantics:
// at the gate, a type-shifted value (the number 5 where a string is
// expected, "true" where a bool is expected) must not satisfy neq and
// slide past the gate. Numeric values normalize across int and float
// representations because YAML decodes 5 as int and JSON decodes it as
// float64: the same number, two sources. Values of different kinds are
// incomparable.
func compare(want, got any) (equal, comparable bool) {
	k := classify(want)
	if k != classify(got) || k == kindOpaque {
		return false, false
	}
	switch k {
	case kindNumber:
		w, wok := toFloat(want)
		g, gok := toFloat(got)
		if !wok || !gok {
			return false, false
		}
		return w == g, true
	case kindString:
		return want.(string) == got.(string), true
	case kindBool:
		return want.(bool) == got.(bool), true
	}
	return false, false
}

// matches applies the operator. An incomparable pair fails for both eq
// and neq: the event is excluded either way, and the trace says which
// check excluded it.
func matches(op Op, want, got any) bool {
	equal, comparable := compare(want, got)
	if !comparable {
		return false
	}
	if op == OpNeq {
		return !equal
	}
	return equal
}

// These tests pin the model client's contract with OpenAI-compatible
// endpoints: schema-validated structured output despite unreliable local
// models. The invariant that matters most is that *InvalidOutputError is
// distinguishable from transport failure — the runtime routes invalid
// output to a retry-with-feedback path and transport failure to an errored
// decision, so conflating them would break the fail-toward-ignore story.
package model

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

func testConfig(baseURL string) Config {
	return Config{Provider: "openai-compatible", BaseURL: baseURL, Model: "mock-model"}
}

func testSchema() Schema {
	min, max := 0.0, 1.0
	return Schema{
		"category":   {Type: "string", Enum: []any{"important", "unimportant"}},
		"importance": {Type: "number", Minimum: &min, Maximum: &max},
	}
}

// chatBody renders a minimal chat completion response carrying the given
// assistant content. Local model servers vary wildly in response shape;
// this is the one shape the client actually depends on.
func chatBody(content string) map[string]any {
	return map[string]any{
		"choices": []any{
			map[string]any{"message": map[string]any{"content": content}},
		},
	}
}

// contentServer serves the given assistant contents in request order,
// repeating the last one if the client asks more times than expected.
// Each HTTP request decodes to exactly one model attempt, which makes the
// sequence the observable behavior under test.
func contentServer(t *testing.T, contents ...string) (*httptest.Server, *int) {
	t.Helper()
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		i := calls
		calls++
		content := contents[len(contents)-1]
		if i < len(contents) {
			content = contents[i]
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(chatBody(content))
	}))
	t.Cleanup(srv.Close)
	return srv, &calls
}

func TestInterpretHappyPath(t *testing.T) {
	srv, calls := contentServer(t, `{"category":"important","importance":0.95}`)
	c := &Client{}
	res, _, model, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err != nil {
		t.Fatalf("Interpret: %v", err)
	}
	if res["category"] != "important" || res["importance"] != 0.95 {
		t.Errorf("result = %v, want category=important importance=0.95", res)
	}
	if model != "mock-model" {
		t.Errorf("model = %q, want mock-model", model)
	}
	if *calls != 1 {
		t.Errorf("endpoint called %d times, want 1 (valid output must not retry)", *calls)
	}
}

func TestInterpretFencedOrProseWrappedJSON(t *testing.T) {
	// Local models routinely wrap JSON in markdown fences or chatter.
	// The client must extract the object rather than fail the parse,
	// otherwise every chatty model looks like a schema violation.
	wrapped := "Sure! Here's my analysis:\n```json\n{\"category\":\"unimportant\",\"importance\":0.1}\n```\nHope that helps."
	srv, _ := contentServer(t, wrapped)
	c := &Client{}
	res, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err != nil {
		t.Fatalf("Interpret with fenced content: %v", err)
	}
	if res["category"] != "unimportant" || res["importance"] != 0.1 {
		t.Errorf("result = %v, want fenced JSON parsed", res)
	}
}

func TestInterpretInvalidThenCorrectedRetry(t *testing.T) {
	// The self-correction path: the first output fails validation and the
	// client replays the conversation with the validation error appended,
	// giving the model one chance to fix itself. The retry request must
	// carry the failed assistant turn so the endpoint can see what to fix.
	var retryHadAssistantTurn bool
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req chatRequest
		json.NewDecoder(r.Body).Decode(&req)
		i := calls
		calls++
		if i == 0 {
			json.NewEncoder(w).Encode(chatBody(`{"category":"not-a-category","importance":"high"}`))
			return
		}
		retryHadAssistantTurn = len(req.Messages) == 4 && req.Messages[2].Role == "assistant"
		json.NewEncoder(w).Encode(chatBody(`{"category":"important","importance":0.9}`))
	}))
	t.Cleanup(srv.Close)

	c := &Client{}
	res, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err != nil {
		t.Fatalf("Interpret after corrected retry: %v", err)
	}
	if res["category"] != "important" {
		t.Errorf("result = %v, want corrected retry output", res)
	}
	if calls != 2 {
		t.Errorf("endpoint called %d times, want 2 (initial + corrected retry)", calls)
	}
	if !retryHadAssistantTurn {
		t.Error("retry request must include the invalid assistant turn for self-correction")
	}
}

func TestInterpretInvalidTwiceReturnsInvalidOutputError(t *testing.T) {
	// After the corrected retry also fails, the client must give up with
	// *InvalidOutputError — not keep retrying, and not a generic error,
	// since the runtime distinguishes invalid from errored decisions.
	srv, calls := contentServer(t, `{"category":"urgent","importance":0.9}`, `still not json`)
	c := &Client{}
	_, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	var inv *InvalidOutputError
	if !errors.As(err, &inv) {
		t.Fatalf("err = %v, want *InvalidOutputError", err)
	}
	if *calls != 2 {
		t.Errorf("endpoint called %d times, want 2 (initial + one retry)", *calls)
	}
}

func TestInterpretResponseFormatFallback(t *testing.T) {
	// Some OpenAI-compatible endpoints reject the response_format
	// parameter with a 400. The client detects that specific failure and
	// retries the same request without response_format, falling back to
	// validation alone to enforce the schema.
	calls := 0
	var lastRequestHadFormat *bool
	hadFormat := false
	lastRequestHadFormat = &hadFormat
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req chatRequest
		json.NewDecoder(r.Body).Decode(&req)
		calls++
		if req.ResponseFormat != nil {
			*lastRequestHadFormat = true
			w.WriteHeader(http.StatusBadRequest)
			fmt.Fprint(w, "response_format is not supported")
			return
		}
		*lastRequestHadFormat = false
		json.NewEncoder(w).Encode(chatBody(`{"category":"important","importance":0.85}`))
	}))
	t.Cleanup(srv.Close)

	c := &Client{}
	res, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err != nil {
		t.Fatalf("Interpret with response_format-rejecting endpoint: %v", err)
	}
	if res["category"] != "important" {
		t.Errorf("result = %v, want fallback (no response_format) result", res)
	}
	if calls != 2 || *lastRequestHadFormat {
		t.Errorf("calls=%d lastHadFormat=%v, want 2 calls with final request omitting response_format", calls, *lastRequestHadFormat)
	}
}

func TestInterpretTransportFailureAfterRetries(t *testing.T) {
	// A hard-down endpoint must surface a transport error (not
	// InvalidOutputError) after the bounded attempt count, with no
	// unbounded retry loop. Attempts are spaced by retryBackoff, so this
	// test costs two backoff periods.
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls++
		w.WriteHeader(http.StatusInternalServerError)
		fmt.Fprint(w, "boom")
	}))
	t.Cleanup(srv.Close)

	c := &Client{}
	_, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err == nil {
		t.Fatal("expected transport error, got nil")
	}
	var inv *InvalidOutputError
	if errors.As(err, &inv) {
		t.Fatalf("transport failure must not be reported as *InvalidOutputError, got %v", err)
	}
	if calls != maxAttempts {
		t.Errorf("endpoint called %d times, want %d (bounded attempts)", calls, maxAttempts)
	}
}

func TestInterpretNonRetryable4xxReturnsImmediately(t *testing.T) {
	// A 401 (bad key) or 404 (bad model name) will never succeed on retry;
	// burning the attempt budget on them just triples the noise per event.
	// Only network errors and 5xx consume the retry budget.
	calls := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls++
		w.WriteHeader(http.StatusUnauthorized)
		fmt.Fprint(w, "bad key")
	}))
	t.Cleanup(srv.Close)

	c := &Client{}
	_, _, _, err := c.Interpret(context.Background(), testConfig(srv.URL), "mock", "classify", testSchema(), []byte(`{}`))
	if err == nil {
		t.Fatal("expected error for 401")
	}
	if calls != 1 {
		t.Errorf("endpoint called %d times, want 1 (non-retryable)", calls)
	}
}

func TestValidate(t *testing.T) {
	min, max := 0.0, 1.0
	schema := Schema{
		"category":   {Type: "string", Enum: []any{"important", "unimportant"}},
		"importance": {Type: "number", Minimum: &min, Maximum: &max},
		"flag":       {Type: "boolean"},
	}
	tests := []struct {
		name    string
		res     map[string]any
		wantErr string // empty = expect success
	}{
		{
			name: "valid",
			res:  map[string]any{"category": "important", "importance": 0.9, "flag": true},
		},
		{
			name:    "wrong type: string where number",
			res:     map[string]any{"category": "important", "importance": "0.9", "flag": true},
			wantErr: `field "importance": want number`,
		},
		{
			name:    "wrong type: number where string",
			res:     map[string]any{"category": 7, "importance": 0.9, "flag": true},
			wantErr: `field "category": want string`,
		},
		{
			name:    "number below minimum",
			res:     map[string]any{"category": "important", "importance": -0.1, "flag": true},
			wantErr: `field "importance": value -0.1 below minimum 0`,
		},
		{
			name:    "number above maximum",
			res:     map[string]any{"category": "important", "importance": 8.0, "flag": true},
			wantErr: `field "importance": value 8 above maximum 1`,
		},
		{
			name:    "wrong type: string where boolean",
			res:     map[string]any{"category": "important", "importance": 0.9, "flag": "true"},
			wantErr: `field "flag": want boolean`,
		},
		{
			name:    "missing field",
			res:     map[string]any{"importance": 0.9, "flag": true},
			wantErr: `missing field "category"`,
		},
		{
			name:    "enum violation",
			res:     map[string]any{"category": "urgent", "importance": 0.9, "flag": true},
			wantErr: `field "category": value urgent not in enum`,
		},
		{
			name:    "unexpected extra field",
			res:     map[string]any{"category": "important", "importance": 0.9, "flag": true, "extra": "nope"},
			wantErr: `unexpected field "extra"`,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := validate(tt.res, schema)
			if tt.wantErr == "" {
				if err != nil {
					t.Errorf("validate(%v) = %v, want nil", tt.res, err)
				}
				return
			}
			if err == nil || err.Error() != tt.wantErr {
				t.Errorf("validate(%v) = %v, want error %q", tt.res, err, tt.wantErr)
			}
		})
	}
}

func TestSchemaMapIncludesNumberBounds(t *testing.T) {
	importance := schemaMap(testSchema())["properties"].(map[string]any)["importance"].(map[string]any)
	if importance["minimum"] != 0.0 || importance["maximum"] != 1.0 {
		t.Errorf("importance schema = %v, want minimum=0 maximum=1", importance)
	}
}

// Poller tests run the full loop against real HTTP servers: a feed server
// standing in for the polled target and the standard mock OpenAI-compatible
// model behind a real SQLite database. The invariants that matter: items
// become events exactly once across repeated polls (dedup, not the cursor,
// is the correctness mechanism), the cursor is persisted and substituted
// into subsequent fetches, and malformed items are skipped without killing
// the poll.
package source

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"sync/atomic"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

// modelMock returns the standard canned OpenAI-compatible response. Every
// ingested item scores unimportant so the pipeline ends in ignore and the
// tests stay quiet.
func modelMock(t *testing.T) (url string, calls *atomic.Int32) {
	t.Helper()
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n.Add(1)
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]any{
			"choices": []any{map[string]any{
				"message": map[string]any{"content": `{"category":"unimportant","importance":0.1}`},
			}},
		})
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &n
}

func testRuntime(t *testing.T, modelURL string) *runtime.Runtime {
	t.Helper()
	db, err := storage.Open(filepath.Join(t.TempDir(), "poller.db"))
	if err != nil {
		t.Fatalf("open storage: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	return &runtime.Runtime{
		DB:       db,
		Client:   &model.Client{},
		ModelCfg: model.Config{Provider: "openai-compatible", BaseURL: modelURL, Model: "mock-model"},
		ModelKey: "mock",
		Prompt:   "classify this event",
		Schema: model.Schema{
			"category":   {Type: "string", Enum: []any{"unimportant"}},
			"importance": {Type: "number"},
		},
		Policy: mustPolicy(),
	}
}

// mustPolicy keeps the struct literal out of every test runtime construction.
func mustPolicy() policy.Policy {
	return policy.Policy{Default: policy.Then{Ignore: true}}
}

func pollerCfg(url string) config.Source {
	return config.Source{
		Name:        "feed",
		Type:        "http-poller",
		URL:         url,
		Every:       time.Minute, // Run is never entered in tests; poll is called directly
		ItemPath:    "items",
		CursorField: "id",
		EventType:   "feed.item.published",
	}
}

func feedServer(t *testing.T, pages ...string) (url string, gotQuery *atomic.Value) {
	t.Helper()
	var n atomic.Int32
	var q atomic.Value
	q.Store("")
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		i := int(n.Add(1)) - 1
		q.Store(r.URL.RawQuery)
		page := pages[len(pages)-1]
		if i < len(pages) {
			page = pages[i]
		}
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, page)
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &q
}

func countEvents(t *testing.T, rt *runtime.Runtime) int {
	t.Helper()
	var n int
	if err := rt.DB.QueryRow(`SELECT COUNT(*) FROM events`).Scan(&n); err != nil {
		t.Fatalf("count events: %v", err)
	}
	return n
}

// TestPollerIngestsEachItemOnce is the core loop: two items become two
// events with a model call each; repolling the same feed adds nothing
// because dedup drops them before the model; a changed feed adds only the
// new item. The cursor must be persisted across the polls.
func TestPollerIngestsEachItemOnce(t *testing.T) {
	modelURL, modelCalls := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"id":"a","title":"first"},
		{"id":"b","title":"second"}]}`,
		`{"items":[
		{"id":"a","title":"first"},
		{"id":"b","title":"second"},
		{"id":"c","title":"third"}]}`)

	rt := testRuntime(t, modelURL)
	p, err := NewHTTPPoller(pollerCfg(feedURL))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}
	ctx := context.Background()

	p.poll(ctx, rt)
	if got := countEvents(t, rt); got != 2 {
		t.Errorf("events after first poll = %d, want 2", got)
	}
	if modelCalls.Load() != 2 {
		t.Errorf("model calls after first poll = %d, want 2", modelCalls.Load())
	}
	if c, _ := rt.DB.Cursor("feed"); c != "b" {
		t.Errorf("cursor after first poll = %q, want b", c)
	}

	p.poll(ctx, rt)
	if got := countEvents(t, rt); got != 3 {
		t.Errorf("events after second poll = %d, want 3 (only the new item)", got)
	}
	// Dedup happens at InsertEvent, before any model call — repolling a
	// known feed must cost no inference.
	if modelCalls.Load() != 3 {
		t.Errorf("model calls after second poll = %d, want 3", modelCalls.Load())
	}
	if c, _ := rt.DB.Cursor("feed"); c != "c" {
		t.Errorf("cursor after second poll = %q, want c", c)
	}
}

// TestPollerSubstitutesCursorIntoURL pins the cursor-based-API case: the
// first fetch has no cursor, later fetches carry the persisted one.
func TestPollerSubstitutesCursorIntoURL(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, gotQuery := feedServer(t, `{"items":[{"id":"a"}]}`)

	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL + "?after={{ .cursor }}")
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	if q := gotQuery.Load().(string); q != "after=" {
		t.Errorf("first poll query = %q, want empty after", q)
	}
	p.poll(context.Background(), rt)
	if q := gotQuery.Load().(string); q != "after=a" {
		t.Errorf("second poll query = %q, want after=a", q)
	}
}

// TestPollerNormalizesItemFields covers the mapping knobs: subject and
// RFC3339 timestamp come from the item, source_event_id comes from the
// cursor field, and the whole item is preserved as data.
func TestPollerNormalizesItemFields(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"id":"x1","title":"Disk full","published":"2026-09-07T12:00:00Z","disk":"nvme0"}]}`)

	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL)
	cfg.SubjectField = "title"
	cfg.TimestampField = "published"
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	// QueryRow, not Query: the pool is a single connection (SetMaxOpenConns(1)),
	// so an open rows iterator would deadlock Inspect below.
	var id string
	if err := rt.DB.QueryRow(`SELECT id FROM events WHERE source = 'feed' LIMIT 1`).Scan(&id); err != nil {
		t.Fatalf("query event: %v", err)
	}
	ins, err := rt.DB.Inspect(id)
	if err != nil {
		t.Fatalf("inspect: %v", err)
	}
	e := ins.Event
	if e.Subject != "Disk full" {
		t.Errorf("subject = %q, want Disk full", e.Subject)
	}
	if e.Type != "feed.item.published" {
		t.Errorf("type = %q, want feed.item.published", e.Type)
	}
	if want := time.Date(2026, 9, 7, 12, 0, 0, 0, time.UTC); !e.Timestamp.Equal(want) {
		t.Errorf("timestamp = %v, want item's %v", e.Timestamp, want)
	}
	if e.Data["disk"] != "nvme0" {
		t.Errorf("data = %v, want the whole item preserved", e.Data)
	}
}

// TestPollerSkipsItemsWithoutCursorField pins the fail-closed dedup rule:
// when cursor_field is configured, an item without it cannot be identified
// and must not be ingested (payload-hash dedup would not catch a changing
// payload, so ingest would duplicate).
func TestPollerSkipsItemsWithoutCursorField(t *testing.T) {
	modelURL, modelCalls := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[
		{"title":"no id here"},
		{"id":"ok","title":"fine"}]}`)

	rt := testRuntime(t, modelURL)
	p, err := NewHTTPPoller(pollerCfg(feedURL))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}

	p.poll(context.Background(), rt)
	if got := countEvents(t, rt); got != 1 {
		t.Errorf("events = %d, want 1 (only the identified item)", got)
	}
	if modelCalls.Load() != 1 {
		t.Errorf("model calls = %d, want 1", modelCalls.Load())
	}
}

// TestPollerFetchFailureKeepsState: a dead target must not crash, ingest
// nothing, or move the cursor; the next tick retries.
func TestPollerFetchFailureKeepsState(t *testing.T) {
	modelURL, _ := modelMock(t)
	rt := testRuntime(t, modelURL)
	rt.DB.SetCursor("feed", "old")

	p, err := NewHTTPPoller(pollerCfg("http://127.0.0.1:1/feed"))
	if err != nil {
		t.Fatalf("NewHTTPPoller: %v", err)
	}
	p.poll(context.Background(), rt) // port 1: connection refused

	if got := countEvents(t, rt); got != 0 {
		t.Errorf("events = %d, want 0", got)
	}
	if c, _ := rt.DB.Cursor("feed"); c != "old" {
		t.Errorf("cursor = %q, want unchanged old", c)
	}
}

// TestPollerIncompleteBatchKeepsCursor exercises failures between two valid
// records. Advancing to either successful record could hide the failed one
// from an incremental API, so the whole batch must retain its old watermark.
func TestPollerIncompleteBatchKeepsCursor(t *testing.T) {
	for _, tc := range []struct {
		name string
		item string
	}{
		{"event write failure", `{"id":"c"}`},
		{"non-object", `null`},
		{"missing id", `{"title":"missing id"}`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			modelURL, modelCalls := modelMock(t)
			feedURL, gotQuery := feedServer(t,
				`{"items":[{"id":"b"},`+tc.item+`,{"id":"d"}]}`,
				`{"items":[{"id":"b"},{"id":"c"},{"id":"d"}]}`)
			rt := testRuntime(t, modelURL)
			if err := rt.DB.SetCursor("feed", "a"); err != nil {
				t.Fatal(err)
			}
			if tc.name == "event write failure" {
				// A SQLite trigger fails just the middle insert without a mock
				// storage layer or making the cursor table unwritable too.
				if _, err := rt.DB.Exec(`CREATE TRIGGER fail_event BEFORE INSERT ON events
					WHEN NEW.dedup_key = 'c' BEGIN SELECT RAISE(FAIL, 'test failure'); END`); err != nil {
					t.Fatal(err)
				}
			}
			p, err := NewHTTPPoller(pollerCfg(feedURL + "?after={{ .cursor }}"))
			if err != nil {
				t.Fatal(err)
			}
			p.poll(context.Background(), rt)
			if c, err := rt.DB.Cursor("feed"); err != nil || c != "a" {
				t.Errorf("cursor after incomplete batch = %q, %v, want a", c, err)
			}
			if got := countEvents(t, rt); got != 2 {
				t.Errorf("events = %d, want both valid records stored", got)
			}
			if modelCalls.Load() != 2 {
				t.Errorf("model calls = %d, want 2", modelCalls.Load())
			}

			// The next page corrects malformed data; removing the trigger
			// simulates recovery from a transient event persistence failure.
			if _, err := rt.DB.Exec(`DROP TRIGGER IF EXISTS fail_event`); err != nil {
				t.Fatal(err)
			}
			p.poll(context.Background(), rt)
			if q := gotQuery.Load().(string); q != "after=a" {
				t.Errorf("retry query = %q, want original after=a", q)
			}
			if c, err := rt.DB.Cursor("feed"); err != nil || c != "d" {
				t.Errorf("cursor after recovery = %q, %v, want d", c, err)
			}
			if got := countEvents(t, rt); got != 3 {
				t.Errorf("events after recovery = %d, want 3", got)
			}
			if modelCalls.Load() != 3 {
				t.Errorf("model calls after recovery = %d, want 3 (successful records dedup)", modelCalls.Load())
			}
		})
	}
}

// TestPollerCanceledLastItemKeepsCursor covers cancellation inside Ingest:
// there is no next loop iteration to notice it, and a canceled model call
// is recorded as an errored decision rather than returned as an ingest error.
func TestPollerCanceledLastItemKeepsCursor(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	modelServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		cancel()
	}))
	defer modelServer.Close()
	feedURL, _ := feedServer(t, `{"items":[{"id":"b"}]}`)
	rt := testRuntime(t, modelServer.URL)
	if err := rt.DB.SetCursor("feed", "a"); err != nil {
		t.Fatal(err)
	}
	p, err := NewHTTPPoller(pollerCfg(feedURL))
	if err != nil {
		t.Fatal(err)
	}
	p.poll(ctx, rt)
	if c, err := rt.DB.Cursor("feed"); err != nil || c != "a" {
		t.Errorf("cursor after cancellation = %q, %v, want a", c, err)
	}
}

// TestCursorSurvivesReopen pins the restart-safety story: the watermark
// lives in SQLite, so a restarted runtime resumes where it left off.
func TestCursorSurvivesReopen(t *testing.T) {
	path := filepath.Join(t.TempDir(), "cursor.db")
	db1, err := storage.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := db1.SetCursor("feed", "42"); err != nil {
		t.Fatal(err)
	}
	db1.Close()

	db2, err := storage.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer db2.Close()
	if c, err := db2.Cursor("feed"); err != nil || c != "42" {
		t.Errorf("cursor after reopen = %q, %v, want 42", c, err)
	}
	if c, err := db2.Cursor("unknown"); err != nil || c != "" {
		t.Errorf("unknown source cursor = %q, %v, want empty, nil", c, err)
	}
}

// TestRunStopsOnContextCancel is the goroutine-contract check: Run owns one
// goroutine, exits when ctx is canceled, and does it promptly.
func TestRunStopsOnContextCancel(t *testing.T) {
	modelURL, _ := modelMock(t)
	feedURL, _ := feedServer(t, `{"items":[]}`)
	rt := testRuntime(t, modelURL)
	cfg := pollerCfg(feedURL)
	cfg.Every = 50 * time.Millisecond // fast ticks; feed returns no items
	p, err := NewHTTPPoller(cfg)
	if err != nil {
		t.Fatal(err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { p.Run(ctx, rt); close(done) }()
	time.Sleep(120 * time.Millisecond) // let at least one tick pass
	cancel()

	select {
	case <-done:
		// stopped promptly
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not stop after context cancel")
	}
}

