	}
}

// These tests pin the events handler, the runtime's only ingress: every way
// untrusted input is rejected (missing type/source, malformed JSON, oversized
// bodies) must fail with a 400 and {"error": ...} before the pipeline —
// SQLite, model call, policy — is ever touched, and a valid event must come
// back as a 200 whose body is the full trace of what happened. The handler
// is exercised directly with a recorder instead of booting the server so a
// failure points at ingress logic, not at the run loop.
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

// modelServer serves canned chat-completion contents over httptest, so
// these tests need no network and no real model. The call count lets the
// rejection cases assert the pipeline was never reached.
func modelServer(t *testing.T, contents ...string) (url string, calls *atomic.Int32) {
	t.Helper()
	var n atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		i := int(n.Add(1)) - 1
		content := contents[len(contents)-1]
		if i < len(contents) {
			content = contents[i]
		}
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, `{"choices":[{"message":{"content":`+fmt.Sprintf("%q", content)+`}}]}`)
	}))
	t.Cleanup(srv.Close)
	return srv.URL, &n
}

// newTestHandler wires a real runtime over a temp-dir SQLite DB and a mock
// model endpoint. The schema and policy mirror the runtime tests: one
// classification contract and a single importance threshold routing to
// stdout, so a canned "important" answer deterministically produces notify.
func newTestHandler(t *testing.T, contents ...string) (http.HandlerFunc, *atomic.Int32) {
	t.Helper()
	url, calls := modelServer(t, contents...)
	db, err := storage.Open(filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatalf("open storage: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	rt := &runtime.Runtime{
		DB:       db,
		Client:   &model.Client{},
		ModelCfg: model.Config{Provider: "openai-compatible", BaseURL: url, Model: "mock-model"},
		ModelKey: "mock",
		Prompt:   "classify this event",
		Schema: model.Schema{
			"category":   {Type: "string", Enum: []any{"important", "unimportant"}},
			"importance": {Type: "number"},
		},
		Policy: policy.Policy{
			Rules: []policy.Rule{{
				If:   map[string]any{"result.importance": "> 0.8"},
				Then: policy.Then{Notify: &policy.Notify{Via: "stdout"}},
			}},
			Default: policy.Then{Ignore: true},
		},
	}
	return eventsHandler(rt), calls
}

// handlerResponse mirrors just the response fields the handler contract
// promises, so the assertions stay about the wire shape and not the
// runtime's internal structs.
type handlerResponse struct {
	EventID  string `json:"event_id"`
	Outcome  string `json:"outcome"`
	Decision *struct {
		Status string         `json:"status"`
		Result map[string]any `json:"result"`
	} `json:"decision"`
}

func post(t *testing.T, h http.HandlerFunc, contentType string, body string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(http.MethodPost, "/api/events", strings.NewReader(body))
	req.Header.Set("Content-Type", contentType)
	rec := httptest.NewRecorder()
	h(rec, req)
	return rec
}

// A failed later source must not activate an earlier poller. In particular,
// journal permission/platform failures must not leave effects running during
// a startup that the user was told failed.
func TestPrepareSourcesDoesNotActivatePartialConfig(t *testing.T) {
	var calls atomic.Int32
	feed := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		fmt.Fprint(w, `[]`)
	}))
	defer feed.Close()
	t.Setenv("PATH", t.TempDir()) // missing journalctl on Linux, platform error elsewhere
	runners, err := prepareSources(context.Background(), []config.Source{
		{Name: "http", Type: "http-poller", URL: feed.URL},
		{Name: "journal", Type: "systemd-journal"},
	}, nil)
	if err == nil || runners != nil || calls.Load() != 0 {
		t.Fatalf("partial activation: runners=%d, err=%v, calls=%d", len(runners), err, calls.Load())
	}
}

func TestEventsHandlerValidEvent(t *testing.T) {
	h, calls := newTestHandler(t, `{"category":"important","importance":0.95}`)

	rec := post(t, h, "application/json", `{"type":"commit.pushed","source":"github","data":{"msg":"fix bug"}}`)
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200 (body: %s)", rec.Code, rec.Body.String())
	}
	var resp handlerResponse
	if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if resp.EventID == "" {
		t.Error("event_id missing from response body")
	}
	if resp.Outcome != "notify" {
		t.Errorf("outcome = %q, want notify (importance 0.95 > 0.8)", resp.Outcome)
	}
	if resp.Decision == nil || resp.Decision.Status != "ok" {
		t.Fatalf("decision = %+v, want an ok decision in the body", resp.Decision)
	}
	if resp.Decision.Result["importance"] != 0.95 {
		t.Errorf("decision result = %v, want the model's validated result", resp.Decision.Result)
	}
	if n := calls.Load(); n != 1 {
		t.Errorf("model called %d times, want 1", n)
	}
}

func TestEventsHandlerRejectsBadRequests(t *testing.T) {
	tests := []struct {
		name string
		body string
	}{
		{
			name: "missing type",
			body: `{"source":"github"}`,
		},
		{
			name: "missing source",
			body: `{"type":"commit.pushed"}`,
		},
		{
			name: "malformed JSON",
			body: `{"type": "commit.pushed", "source":`,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			h, calls := newTestHandler(t, `{"category":"important","importance":0.95}`)
			rec := post(t, h, "application/json", tt.body)
			if rec.Code != http.StatusBadRequest {
				t.Fatalf("status = %d, want 400 (body: %s)", rec.Code, rec.Body.String())
			}
			if got := rec.Body.String(); !strings.Contains(got, `"error"`) {
				t.Errorf("body = %s, want an {\"error\": ...} envelope", got)
			}
			// Rejection must happen before the pipeline: nothing persisted
			// and, as the cheapest observable proxy, no model call.
			if n := calls.Load(); n != 0 {
				t.Errorf("model called %d times, want 0 (rejected input must not reach the pipeline)", n)
			}
		})
	}
}

func TestEventsHandlerRejectsOversizedBody(t *testing.T) {
	h, calls := newTestHandler(t, `{"category":"important","importance":0.95}`)
	// The body is valid JSON but padded past the 1 MiB ingress bound; the
	// limit must trip before the event is constructed or anything persists.
	pad := strings.Repeat("a", 1<<20+64)
	rec := post(t, h, "application/json", `{"type":"t","source":"s","data":{"pad":"`+pad+`"}}`)
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400 for body over the 1 MiB bound", rec.Code)
	}
	if got := rec.Body.String(); !strings.Contains(got, `"error"`) {
		t.Errorf("body = %s, want an {\"error\": ...} envelope", got)
	}
	if n := calls.Load(); n != 0 {
		t.Errorf("model called %d times, want 0 (oversized input must not reach the pipeline)", n)
	}
}

// These tests pin storage's durability and dedup contracts. Dedup is the
// runtime's exactly-once guarantee: a redelivered webhook must not produce
// a second decision, so the (source, dedup_key) uniqueness — via
// source_event_id or payload hash — is behavior users depend on, not an
// implementation detail. Migration idempotence matters because every
// process restart reopens the same database file.
package storage

import (
	"encoding/json"
	"path/filepath"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
)

func testEvent(sourceEventID string, data map[string]any) event.Event {
	e := event.Event{
		ID:        event.NewID("evt_"),
		Type:      "commit.pushed",
		Source:    "github",
		Subject:   "mrmr",
		Timestamp: time.Now().UTC(),
		Data:      data,
	}
	if sourceEventID != "" {
		e.Metadata = map[string]any{"source_event_id": sourceEventID}
	}
	return e
}

func openTestDB(t *testing.T) *DB {
	t.Helper()
	d, err := Open(filepath.Join(t.TempDir(), "test.db"))
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	t.Cleanup(func() { d.Close() })
	return d
}

func TestInsertEventDuplicateBySourceEventID(t *testing.T) {
	d := openTestDB(t)
	first := testEvent("gh-123", map[string]any{"sha": "abc"})
	rec, err := d.InsertEvent(first)
	if err != nil {
		t.Fatalf("insert first: %v", err)
	}
	if rec.Duplicate {
		t.Error("first insert must not be a duplicate")
	}

	// A second event carrying the same source_event_id — as a webhook
	// redelivery would — is the same upstream occurrence even though the
	// mrmr-side event ID differs.
	second := testEvent("gh-123", map[string]any{"sha": "abc"})
	rec, err = d.InsertEvent(second)
	if err != nil {
		t.Fatalf("insert second: %v", err)
	}
	if !rec.Duplicate {
		t.Error("same source_event_id must be detected as duplicate")
	}
}

func TestInsertEventDuplicateByPayloadHash(t *testing.T) {
	d := openTestDB(t)
	// No source_event_id: dedup falls back to hashing type + data.
	// Identical payloads from the same source are treated as one event.
	a := testEvent("", map[string]any{"sha": "abc", "msg": "fix"})
	b := testEvent("", map[string]any{"sha": "abc", "msg": "fix"})
	if rec, err := d.InsertEvent(a); err != nil || rec.Duplicate {
		t.Fatalf("first insert: rec=%v err=%v, want non-duplicate", rec, err)
	}
	rec, err := d.InsertEvent(b)
	if err != nil {
		t.Fatalf("second insert: %v", err)
	}
	if !rec.Duplicate {
		t.Error("same payload with no source_event_id must be detected as duplicate")
	}

	// Different data hashes differently, so distinct events pass through.
	c := testEvent("", map[string]any{"sha": "def", "msg": "other"})
	rec, err = d.InsertEvent(c)
	if err != nil {
		t.Fatalf("third insert: %v", err)
	}
	if rec.Duplicate {
		t.Error("different payload must not be a duplicate")
	}
}

func TestDecisionRoundTrip(t *testing.T) {
	d := openTestDB(t)
	ev, err := d.InsertEvent(testEvent("gh-1", nil))
	if err != nil {
		t.Fatalf("insert event: %v", err)
	}
	dec := event.Decision{
		ID:          event.NewID("dec_"),
		EventID:     ev.Event.ID,
		Interpreter: "local",
		Model:       "mock-model",
		Status:      "ok",
		Result:      map[string]any{"category": "important", "importance": 0.9},
		LatencyMs:   42,
	}
	if err := d.InsertDecision(dec); err != nil {
		t.Fatalf("insert decision: %v", err)
	}

	var (
		resultJSON, status, model, interpreter string
		latency                                int64
	)
	err = d.QueryRow(`SELECT interpreter, model, status, result, latency_ms FROM decisions WHERE id = ?`, dec.ID).
		Scan(&interpreter, &model, &status, &resultJSON, &latency)
	if err != nil {
		t.Fatalf("query decision: %v", err)
	}
	if interpreter != dec.Interpreter || model != dec.Model || status != "ok" || latency != 42 {
		t.Errorf("round trip got interpreter=%q model=%q status=%q latency=%d, want original", interpreter, model, status, latency)
	}
	var result map[string]any
	if err := json.Unmarshal([]byte(resultJSON), &result); err != nil {
		t.Fatalf("unmarshal result: %v", err)
	}
	if result["category"] != "important" || result["importance"] != 0.9 {
		t.Errorf("result = %v, want marshaled decision result back", result)
	}
}

func TestExecutionRoundTrip(t *testing.T) {
	d := openTestDB(t)
	ev, err := d.InsertEvent(testEvent("gh-2", nil))
	if err != nil {
		t.Fatalf("insert event: %v", err)
	}
	// executions.decision_id carries a foreign key, so the decision row
	// must exist first — the audit chain events → decisions → executions
	// is enforced by the schema, not by convention.
	dec := event.Decision{
		ID: "dec_1", EventID: ev.Event.ID, Interpreter: "mock", Model: "mock-model",
		Status: "ok", Result: map[string]any{"importance": 0.9}, LatencyMs: 42,
	}
	if err := d.InsertDecision(dec); err != nil {
		t.Fatalf("insert decision: %v", err)
	}
	if err := d.InsertExecution("exe_1", ev.Event.ID, "dec_1", "notify", "stdout", "ok", ""); err != nil {
		t.Fatalf("insert execution: %v", err)
	}
	var eventID, decisionID, outcome, adapter, status, execErr string
	err = d.QueryRow(`SELECT event_id, decision_id, outcome, adapter, status, error FROM executions WHERE id = ?`, "exe_1").
		Scan(&eventID, &decisionID, &outcome, &adapter, &status, &execErr)
	if err != nil {
		t.Fatalf("query execution: %v", err)
	}
	if eventID != ev.Event.ID || decisionID != "dec_1" || outcome != "notify" || adapter != "stdout" || status != "ok" || execErr != "" {
		t.Errorf("round trip got eventID=%q dec=%q outcome=%q adapter=%q status=%q err=%q, want original values",
			eventID, decisionID, outcome, adapter, status, execErr)
	}
}

func TestMigrationsIdempotentOnReopen(t *testing.T) {
	path := filepath.Join(t.TempDir(), "test.db")
	d1, err := Open(path)
	if err != nil {
		t.Fatalf("first Open: %v", err)
	}
	d1.Close()

	// Reopening the same file — what every process restart does — must
	// not re-apply migrations or fail. Version bookkeeping in
	// schema_migrations makes the second open a no-op.
	d2, err := Open(path)
	if err != nil {
		t.Fatalf("second Open of migrated DB: %v", err)
	}
	defer d2.Close()

	var applied int
	if err := d2.QueryRow(`SELECT COUNT(*) FROM schema_migrations`).Scan(&applied); err != nil {
		t.Fatalf("count migrations: %v", err)
	}
	if applied != len(migrations) {
		t.Errorf("applied migrations = %d, want %d (each exactly once)", applied, len(migrations))
	}
}

// These tests pin the filter gate's contract: deterministic, fail
// toward ignore, value-free reasons. The cases that matter most are the
// bypass cases: a missing field must not pass neq, and a type-shifted
// value must not satisfy either operator.
package filter

import (
	"fmt"
	"math"
	"strings"
	"testing"

	"github.com/heath0xff/mrmr/internal/event"
)

func evt(data, meta map[string]any) event.Event {
	return event.Event{
		Type:     "commit.pushed",
		Source:   "github",
		Subject:  "mrmr",
		Data:     data,
		Metadata: meta,
	}
}

func TestEvaluatePassAndFail(t *testing.T) {
	tests := []struct {
		name  string
		specs List
		e     event.Event
		want  bool
	}{
		{"neq passes a different value", List{{Field: "data.author", Op: OpNeq, Value: "dependabot[bot]"}}, evt(map[string]any{"author": "alice"}, nil), true},
		{"neq excludes an equal value", List{{Field: "data.author", Op: OpNeq, Value: "dependabot[bot]"}}, evt(map[string]any{"author": "dependabot[bot]"}, nil), false},
		{"empty op defaults to eq", List{{Field: "data.author", Value: "alice"}}, evt(map[string]any{"author": "alice"}, nil), true},
		{"eq excludes a different value", List{{Field: "data.author", Op: OpEq, Value: "alice"}}, evt(map[string]any{"author": "bob"}, nil), false},
		{"numbers normalize int vs float", List{{Field: "data.count", Value: 5}}, evt(map[string]any{"count": 5.0}, nil), true},
		{"numbers compare across representations", List{{Field: "data.count", Op: OpNeq, Value: 5.0}}, evt(map[string]any{"count": 4}, nil), true},
		{"bools compare as bools", List{{Field: "data.flag", Value: true}}, evt(map[string]any{"flag": true}, nil), true},
		{"top-level type", List{{Field: "type", Op: OpNeq, Value: "spam.ping"}}, evt(nil, nil), true},
		{"top-level source", List{{Field: "source", Value: "github"}}, evt(nil, nil), true},
		{"subject", List{{Field: "subject", Value: "mrmr"}}, evt(nil, nil), true},
		{"nested data path", List{{Field: "data.a.b", Value: "x"}}, evt(map[string]any{"a": map[string]any{"b": "x"}}, nil), true},
		{"metadata path", List{{Field: "metadata.source_event_id", Value: "gh-1"}}, evt(nil, map[string]any{"source_event_id": "gh-1"}), true},
		{"event prefix form", List{{Field: "event.data.author", Op: OpNeq, Value: "dependabot[bot]"}}, evt(map[string]any{"author": "alice"}, nil), true},
		{"empty list passes", List{}, evt(nil, nil), true},
		{"all specs must pass", List{{Field: "type", Value: "commit.pushed"}, {Field: "data.author", Value: "alice"}}, evt(map[string]any{"author": "bob"}, nil), false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, _ := tt.specs.Evaluate(tt.e)
			if got != tt.want {
				t.Fatalf("Evaluate() = %v, want %v", got, tt.want)
			}
		})
	}
}

// TestEvaluateMissingFieldFailsEveryOp pins the gate rule: a field the
// event does not carry fails the filter for every operator. In
// particular neq must not pass a missing field, or a malformed event
// bypasses the pre-model gate and reaches policy, which can authorize
// outcomes.
func TestEvaluateMissingFieldFailsEveryOp(t *testing.T) {
	for _, op := range []Op{"", OpEq, OpNeq} {
		t.Run("op="+string(op), func(t *testing.T) {
			specs := List{{Field: "data.author", Op: op, Value: "dependabot[bot]"}}
			if got, _ := specs.Evaluate(evt(nil, nil)); got {
				t.Fatal("Evaluate() = true for a missing field, want excluded")
			}
		})
	}
}

// TestEvaluateTypeMismatchFailsBothOps pins the second bypass rule: a
// type-shifted value is incomparable and fails both operators. The
// fmt.Sprint equality this package deliberately does not use would let
// true satisfy a "true" check and let a number slide past a string neq.
func TestEvaluateTypeMismatchFailsBothOps(t *testing.T) {
	tests := []struct {
		name  string
		specs List
		e     event.Event
	}{
		{"bool want, string got, neq", List{{Field: "data.flag", Op: OpNeq, Value: true}}, evt(map[string]any{"flag": "true"}, nil)},
		{"bool want, string got, eq", List{{Field: "data.flag", Value: true}}, evt(map[string]any{"flag": "true"}, nil)},
		{"string want, number got, neq", List{{Field: "data.author", Op: OpNeq, Value: "dependabot[bot]"}}, evt(map[string]any{"author": 5}, nil)},
		{"number want, string got, eq", List{{Field: "data.count", Value: 5}}, evt(map[string]any{"count": "5"}, nil)},
		{"number want, string got, neq", List{{Field: "data.count", Op: OpNeq, Value: 5}}, evt(map[string]any{"count": "5"}, nil)},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got, _ := tt.specs.Evaluate(tt.e); got {
				t.Fatal("Evaluate() = true for a type mismatch, want excluded")
			}
		})
	}
}

// TestEvaluateReasonIsValueFree pins the privacy rule: the failure
// reason reaches the trace, the HTTP response, and stdout, so it may
// carry the rule index, field path, and operator only. Event payload
// and configured values must never appear in it.
func TestEvaluateReasonIsValueFree(t *testing.T) {
	specs := List{{Field: "data.token", Op: OpNeq, Value: "expected-secret"}}
	e := evt(map[string]any{"token": "expected-secret"}, nil)
	got, reason := specs.Evaluate(e)
	if got {
		t.Fatal("Evaluate() = true, want excluded")
	}
	for _, leaked := range []string{"expected-secret"} {
		if strings.Contains(reason, leaked) {
			t.Errorf("reason %q leaks %q", reason, leaked)
		}
	}
	if reason != "filter 1: data.token (neq) did not match" {
		t.Errorf("reason = %q, want the value-free form", reason)
	}
}

// TestEvaluateReasonNamesTheFailingRule pins that the reason identifies
// which rule excluded the event, so the trace answers "why" without
// reading the config.
func TestEvaluateReasonNamesTheFailingRule(t *testing.T) {
	specs := List{
		{Field: "type", Value: "commit.pushed"},
		{Field: "metadata.source_event_id", Op: OpNeq, Value: "dup-1"},
	}
	e := evt(nil, map[string]any{"source_event_id": "dup-1"})
	got, reason := specs.Evaluate(e)
	if got {
		t.Fatal("Evaluate() = true, want excluded")
	}
	if reason != "filter 2: metadata.source_event_id (neq) did not match" {
		t.Errorf("reason = %q, want the second rule named", reason)
	}
}

func TestSpecValidate(t *testing.T) {
	tests := []struct {
		name string
		spec Spec
		want string
	}{
		{"empty field", Spec{Op: OpEq, Value: "x"}, "field is required"},
		{"unknown root", Spec{Field: "foo.bar", Op: OpEq, Value: "x"}, `unknown root "foo"`},
		{"bare data root", Spec{Field: "data", Op: OpEq, Value: "x"}, "data requires a sub-path"},
		{"bare metadata root", Spec{Field: "metadata", Op: OpEq, Value: "x"}, "metadata requires a sub-path"},
		{"sub-path under scalar root", Spec{Field: "type.x", Op: OpEq, Value: "x"}, "type has no sub-paths"},
		{"double event prefix", Spec{Field: "event.event.data.x", Op: OpEq, Value: "x"}, `unknown root "event"`},
		{"empty segment", Spec{Field: "data..x", Op: OpEq, Value: "x"}, "empty path segment"},
		{"trailing dot", Spec{Field: "data.x.", Op: OpEq, Value: "x"}, "empty path segment"},
		{"unknown op", Spec{Field: "data.author", Op: "lt", Value: "x"}, `op "lt" not supported`},
		{"missing value", Spec{Field: "data.author", Op: OpNeq, Value: nil}, "value is required"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := tt.spec.Validate()
			if err == nil {
				t.Fatal("Validate() = nil, want error")
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Errorf("Validate() error = %q, want containing %q", err, tt.want)
			}
		})
	}
}

// TestSpecValidateAcceptsDocumentedForms pins the two documented
// spellings of a filter field (section 3 and the flow example) plus the
// scalar-root and metadata forms, so strict validation never rejects a
// documented example.
func TestSpecValidateAcceptsDocumentedForms(t *testing.T) {
	specs := []Spec{
		{Field: "data.author", Op: OpNeq, Value: "x"},
		{Field: "event.data.author", Op: OpNeq, Value: "x"},
		{Field: "event.type", Value: "x"},
		{Field: "metadata.source_event_id", Op: "", Value: 5},
	}
	for _, s := range specs {
		if err := s.Validate(); err != nil {
			t.Errorf("Validate(%+v) = %v, want nil", s, err)
		}
	}
}

// TestEvaluateEmptySubjectFailsNeq pins the optional-field rule:
// subject is optional, so an event without one has no value to
// compare. neq must not treat the empty string as a value that differs
// from the excluded one, or a subject-less event slips past the gate.
func TestEvaluateEmptySubjectFailsNeq(t *testing.T) {
	specs := List{{Field: "subject", Op: OpNeq, Value: "blocked"}}
	e := event.Event{Type: "commit.pushed", Source: "github"}
	if got, _ := specs.Evaluate(e); got {
		t.Fatal("Evaluate() = true for an empty subject, want excluded")
	}
}

// TestEvaluateEmptyScalarRootsFailNeq pins the same guard on type and
// source: Ingest can be called outside the HTTP handler, which is the
// only place that requires them non-empty, so an empty value there is
// not present, not a comparison.
func TestEvaluateEmptyScalarRootsFailNeq(t *testing.T) {
	for _, field := range []string{"type", "source", "subject"} {
		t.Run(field, func(t *testing.T) {
			specs := List{{Field: field, Op: OpNeq, Value: "blocked"}}
			if got, _ := specs.Evaluate(event.Event{}); got {
				t.Fatal("Evaluate() = true for an empty scalar root, want excluded")
			}
		})
	}
}

// TestSpecValidateRejectsNonFiniteFloat32 pins the config-side half of
// the non-finite rule for the float32 kind: a NaN or Inf config value
// can never match, so it must fail startup rather than silently
// exclude every event at runtime.
func TestSpecValidateRejectsNonFiniteFloat32(t *testing.T) {
	for _, v := range []any{float32(math.NaN()), float32(math.Inf(1))} {
		spec := Spec{Field: "data.score", Op: OpNeq, Value: v}
		if err := spec.Validate(); err == nil {
			t.Fatalf("Validate() = nil for %v, want a non-finite value error", v)
		}
	}
}

// TestEvaluateNonFiniteEventValueFails pins the event-side half: a NaN
// or Inf value in event data is not comparable, so it fails both
// operators. Without the guard, neq passes every non-finite value and
// malformed data slips past the gate.
func TestEvaluateNonFiniteEventValueFails(t *testing.T) {
	for _, v := range []any{math.NaN(), math.Inf(1)} {
		for _, op := range []Op{OpEq, OpNeq} {
			t.Run(fmt.Sprintf("%v-%s", v, op), func(t *testing.T) {
				specs := List{{Field: "data.score", Op: op, Value: 0.5}}
				if got, _ := specs.Evaluate(evt(map[string]any{"score": v}, nil)); got {
					t.Fatal("Evaluate() = true for a non-finite event value, want excluded")
				}
			})
		}
	}
}

