	for _, field := range []string{`"metadata":{"source_event_id":%s}`, `"data":{"id":%s}`} {
		h, calls := newTestHandler(t, `{"category":"unimportant","importance":0.1}`)
		for i, id := range []string{"9007199254740992", "9007199254740993", "9007199254740993"} {
